constexpr bool offsetsRise() {
    for (std::size_t i = 1; i < kWorkbenchFields.size(); ++i)
        if (kWorkbenchFields[i - 1].offset >= kWorkbenchFields[i].offset) return false;
    return true;
}
static_assert(offsetsRise(), "the ivar table must be ordered and duplicate-free");

constexpr std::size_t offsetOf(std::string_view want) {
    for (const Field& f : kWorkbenchFields)
        if (f.name == want) return f.offset;
    return static_cast<std::size_t>(-1);
}

static_assert(offsetOf("craftingItemObject") == 180);
static_assert(offsetOf("selectedIndex") == 136);
static_assert(offsetOf("numberOfCraftableItems") == 124);
static_assert(offsetOf("type") == 120);
static_assert(offsetOf("sourceItems") == 140);

